<?php
require __DIR__.'/../config/app.php';$me=require_role('committee');ensure_committee_schema();$eventFilter=max(0,(int)($_GET['event_id']??0));$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');
    if(!in_array($status,['Pending','Shortlisted','Approved','Rejected','Waitlisted'],true)){$error='Choose a valid application status.';}
    else try{$pdo=db();$q=$pdo->prepare('SELECT a.user_id,e.title FROM event_applications a JOIN events e ON e.id=a.event_id JOIN committee_event_assignments cea ON cea.event_id=e.id AND cea.committee_user_id=? WHERE a.id=?');$q->execute([$me['id'],$id]);$application=$q->fetch();if(!$application){$error='Application not found in your assigned events.';}else{$pdo->beginTransaction();$pdo->prepare('UPDATE event_applications SET status=? WHERE id=?')->execute([$status,$id]);$notify=$pdo->prepare('INSERT INTO notifications(user_id,title,message) SELECT ?,?,? WHERE COALESCE((SELECT in_app_notifications FROM user_settings WHERE user_id=?),1)=1');$notify->execute([$application['user_id'],'Application status updated',$application['title'].' application status is now '.$status.'.',$application['user_id']]);$pdo->commit();flash('Application status updated.');go('committee/applications.php'.($eventFilter?'?event_id='.$eventFilter:''));}}catch(Throwable $t){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error='Could not update this application.';}
}
$rows=[];$assignedEvents=[];
try{$pdo=db();$q=$pdo->prepare('SELECT e.id,e.title FROM committee_event_assignments cea JOIN events e ON e.id=cea.event_id WHERE cea.committee_user_id=? ORDER BY e.event_date,e.title');$q->execute([$me['id']]);$assignedEvents=$q->fetchAll();$sql='SELECT a.id,a.status,a.applied_at,u.name,u.email,e.id event_id,e.title,e.category,e.event_date,e.venue FROM event_applications a JOIN users u ON u.id=a.user_id JOIN events e ON e.id=a.event_id JOIN committee_event_assignments cea ON cea.event_id=e.id AND cea.committee_user_id=?';$args=[$me['id']];if($eventFilter){$sql.=' AND e.id=?';$args[]=$eventFilter;}$sql.=' ORDER BY a.applied_at DESC';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();}catch(Throwable $t){}
$pageTitle='Event Applications';$activePage='applications';$bodyClass='dashboard-page committee-page';$hideSiteNav=true;require __DIR__.'/../includes/header.php';
?><div class="dash-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content committee-content"><header class="admin-page-heading"><div><span class="admin-eyebrow">COMMITTEE WORKSPACE</span><h1>Event Applications</h1><p>Review applications only for events assigned to you.</p></div></header><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('clipboard')?></span><div><h2>Applications <span class="admin-count"><?=count($rows)?></span></h2><p>Changing status sends an in-app notification if the student has notifications enabled.</p></div></div><?php if($assignedEvents):?><form class="committee-event-filter" method="get"><label>Assigned event<select name="event_id" onchange="this.form.submit()"><option value="">All assigned events</option><?php foreach($assignedEvents as $event):?><option value="<?=$event['id']?>" <?=$eventFilter===(int)$event['id']?'selected':''?>><?=e($event['title'])?></option><?php endforeach;?></select></label></form><?php endif;?><?php if($rows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Student</th><th>Event</th><th>Category</th><th>Applied on</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $application):?><tr><td><strong><?=e($application['name'])?></strong><small><?=e($application['email'])?></small></td><td><?=e($application['title'])?></td><td><span class="pill <?=e($application['category'])?>"><?=e(ucfirst($application['category']))?></span></td><td><?=date('d M Y',strtotime($application['applied_at']))?></td><td><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$application['id']?>"><select class="application-status" name="status" onchange="this.form.submit()" aria-label="Application status for <?=e($application['name'])?>"><?php foreach(['Pending','Shortlisted','Approved','Rejected','Waitlisted'] as $status):?><option <?=$application['status']===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty"><?=$assignedEvents?'No applications for the selected assigned events yet.':'No events are assigned to your account yet. Ask an administrator to assign an event.'?></div><?php endif;?></section></main></div><?php require __DIR__.'/../includes/footer.php';
